module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);
wire [15:0] sum;
wire [15:0] carry;

// 8-bit adder instantiation
wire [7:0] sum_low;
wire [7:0] sum_high;
wire carry_low;
wire carry_high;

// Low bits
assign {carry_low, sum_low} = a[7:0] + b[7:0] + Cin;

// High bits
assign {carry_high, sum_high} = a[15:8] + b[15:8] + carry_low;

// Output assignment
assign sum = {sum_high, sum_low};
assign carry = {carry_high, carry_low};

assign y = sum;
assign Co = carry[15];

endmodule
